INSERT INTO platform_settings (key, value, description) VALUES
 ('catalog_pergola_types', '["Louvered — Tilt Only","Louvered — Retractable","Retractable Fabric Roof","Fixed Fabric Roof","Fixed Solid Roof","Fixed Glass Roof","Retractable Glass Roof","Polycarbonate Roof","Solar Panel Roof","Open Slat / Lattice","Other","Not Sure"]', 'Pergola types offered in the request form'),
