 ('catalog_enclosure_types', '[{"label":"Motorized Guillotine Window","code":"glass"},{"label":"Manual Guillotine Window","code":"glass"},{"label":"Bi-Fold Door","code":"glass"},{"label":"Sliding Door","code":"glass"},{"label":"Lift & Slide Door","code":"glass"},{"label":"French Door","code":"glass"},{"label":"Fixed Glass Wall","code":"glass"},{"label":"Roll-Up Zip Screen","code":"screen"},{"label":"Fixed Aluminum Composite Wall","code":"privacy_wall"},{"label":"Glass Railing","code":"railing"},{"label":"Aluminum Railing","code":"railing"},{"label":"Mosquito Screen","code":"screen"}]', 'Side enclosures & subsystems; code = pricing_rules code'),
 ('catalog_accessories', '[{"label":"LED Lights","code":"led_lighting"},{"label":"Fan","code":"fan"},{"label":"Electric Heater","code":"electric_heater"},{"label":"Gas Heater","code":"gas_heater"},{"label":"Speakers","code":"speaker"},{"label":"Smart Controls / Remote","code":"motor_controls"},{"label":"Rain & Wind Sensor","code":"sensor"},{"label":"Privacy Curtains","code":"curtains"}]', 'Accessories (mounting only); code = pricing_rules code'),
 ('catalog_pergola_systems', '["Suntent","StruXure","Alumawood","Renson","Azenco","Other"]', 'Pergola systems a contractor can declare'),
 ('catalog_electronics_devices', '["Drive motor (roof louvers)","Gearbox","Rain sensor","Wind sensor","Sun sensor","Remote control","Wall controller","Power supply / transformer","Control board","LED driver / dimmer"]', 'Devices selectable in an electronics claim'),
 ('content_home_promo', '{"label":"Limited offer","title":"50% off care plans","sub":"Members offer · this season","cta":"View MrCare plans","enabled":true}', 'Promo card on the consumer home screen'),
 ('content_care_tips', '{"rain":"Rain is expected. Check that your gutters and drainage outlets are clear of leaves and debris.","thunder":"Thunderstorms in the area. Keep clear of the structure during lightning and consider switching off mounted electrical accessories at the source.","snow":"Snow is expected. Follow your manufacturer''s snow-load and roof-operation guidance; clear accumulation only as they advise.","windy":"Strong winds are forecast. Retract zip screens before gusts arrive and follow your manufacturer''s guidance.","sunny":"Sunny days ahead. Check that your screens are clean and operating smoothly.","partly":"Mild conditions. A good time for a quick visual check of louvers, gutters and fixings."}', 'Weather-based pergola care tips'),
 ('content_faq_pro', '[["How do I get activated?","Complete the Core and Safety training, then at least one category module. Installation and Repair also need a supervised first job (practical assessment)."],["When do I get paid?","Earnings land in your balance when the client confirms the work. Withdraw any time above the minimum payout, or turn on automatic payouts."],["What if the client reports an issue?","You will see their feedback and photos. You can return to fix it (no charge to the client) or dispute it — MrBuilder reviews disputes within 48 hours."],["Can I change the price?","No. Quotes are generated by MrBuilder from the request. Extra work goes through a new request or an admin re-quote."],["What are the cancellation fees?","1% of the job if you cancel after accepting but before starting; 5% after starting. Pausing for safety is always free."],["Who covers parts?","Order from Mr Supply straight to the job. Depending on the job, parts are paid by you (reimbursed on the invoice) or by the client."]]', 'PRO app FAQ'),
 ('content_support', '{"phone":"(800) 555-0199","email":"support@mrbuilder.com","hours":"Mon–Sat 7am–7pm PT"}', 'Support contact shown in apps'),
 ('legal_terms', '{"updated":"September 1, 2026","sections":[["1. The platform","MrBuilder connects pergola owners with independent, trained contractors. MrBuilder sets prices, holds payment until the customer confirms the work, and reviews disputes."],["2. Contractors","Contractors are independent businesses. Activation requires completing training and, for some categories, a supervised assessment. Before-work photos and a safety checklist are required before every job."],["3. Payments","Customers are charged only after confirming completed work (or after 72 hours without action). Contractor earnings are released on confirmation. Cancellation fees: 1% before start, 5% after start."],["4. Scope","Structural footings, electrical wiring, gas, plumbing and water-supply work are outside MrBuilder''s scope. Accessories are mounted only."],["5. Disputes","Either party may raise an issue. MrBuilder reviews evidence and decides; decisions may include a return visit at no charge or release of payment."]]}', 'Terms of Service'),
 ('legal_privacy', '{"updated":"September 1, 2026","sections":[["What we collect","Account details, job addresses, photos taken for jobs, device location while using the app (for matching and ETA), payment tokens from our payment provider."],["How we use it","To match jobs, price requests, share job details between customer and contractor, process payments, send notifications and resolve disputes."],["Sharing","Job details are shared between the customer and the assigned contractor only. Payment card data is stored by our payment provider; MrBuilder never sees full card numbers."],["Your rights","Export or delete your data from Settings. Deleted accounts are deactivated immediately and purged after 30 days."]]}', 'Privacy Policy')
